-- Core identity and document metadata. UUIDs are generated by application code.
CREATE TABLE users (
    id uuid PRIMARY KEY,
    issuer text NOT NULL CHECK (length(issuer) BETWEEN 1 AND 2048),
    subject text NOT NULL CHECK (length(subject) BETWEEN 1 AND 512),
    is_active boolean NOT NULL DEFAULT true,
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT uq_users_issuer_subject UNIQUE (issuer, subject)
);

CREATE TABLE documents (
    id uuid PRIMARY KEY,
    owner_id uuid NOT NULL REFERENCES users(id),
    original_filename varchar(255) NOT NULL,
    content_type text NOT NULL DEFAULT 'application/pdf' CHECK (content_type = 'application/pdf'),
    size_bytes bigint NOT NULL CHECK (size_bytes > 0),
    sha256 char(64) NOT NULL CHECK (sha256 ~ '^[0-9a-f]{64}$'),
    object_key text NOT NULL CHECK (length(object_key) BETWEEN 1 AND 2048),
    object_version_id text,
    state text NOT NULL CHECK (state IN ('uploading', 'queued', 'processing', 'ready', 'failed', 'deleting', 'deleted')),
    active_version_id uuid,
    page_count integer CHECK (page_count IS NULL OR page_count >= 0),
    extracted_character_count bigint CHECK (extracted_character_count IS NULL OR extracted_character_count >= 0),
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now(),
    deleted_at timestamptz,
    CONSTRAINT ck_documents_deleted_timestamp CHECK ((state = 'deleted') = (deleted_at IS NOT NULL)),
    CONSTRAINT uq_documents_owner_id UNIQUE (owner_id, id)
);

CREATE UNIQUE INDEX uq_documents_owner_live_sha256
    ON documents (owner_id, sha256) WHERE deleted_at IS NULL;
CREATE INDEX ix_documents_owner_created_id
    ON documents (owner_id, created_at DESC, id DESC);
CREATE INDEX ix_documents_owner_state_created
    ON documents (owner_id, state, created_at DESC, id DESC);

CREATE TABLE document_versions (
    id uuid PRIMARY KEY,
    document_id uuid NOT NULL REFERENCES documents(id),
    version_number integer NOT NULL CHECK (version_number > 0),
    attempt_id uuid NOT NULL,
    state text NOT NULL CHECK (state IN ('indexing', 'ready', 'failed', 'superseded', 'deleting', 'deleted')),
    index_fingerprint char(64) NOT NULL CHECK (index_fingerprint ~ '^[0-9a-f]{64}$'),
    chunk_count integer CHECK (chunk_count IS NULL OR chunk_count >= 0),
    vector_namespace text,
    created_at timestamptz NOT NULL DEFAULT now(),
    ready_at timestamptz,
    CONSTRAINT uq_document_versions_number UNIQUE (document_id, version_number),
    CONSTRAINT uq_document_versions_attempt UNIQUE (document_id, attempt_id),
    CONSTRAINT uq_document_versions_id_document UNIQUE (document_id, id),
    CONSTRAINT ck_document_versions_ready_timestamp CHECK (state <> 'ready' OR ready_at IS NOT NULL)
);

ALTER TABLE documents
    ADD CONSTRAINT fk_documents_active_version
    FOREIGN KEY (id, active_version_id)
    REFERENCES document_versions (document_id, id)
    DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX ix_document_versions_document_created
    ON document_versions (document_id, created_at DESC, id DESC);
